bool elapsed(uint32_t now,uint32_t since,uint32_t duration){return uint32_t(now-since)>=duration;}
void setText(char* dst,size_t cap,const char* value){strlcpy(dst,value?value:"",cap);}
const char* diagText(){switch(diag){case Diag::Idle:return "Non lance";case Diag::Running:return "En cours";case Diag::ResetReceived:return "Reponse recue";case Diag::Absent:return "NanoBCU non detecte";case Diag::ProtocolError:return "Erreur de protocole";case Diag::BusMonitor:return "Bus monitor passif";}return "Inconnu";}
const char* wifiReason(uint8_t r){switch(r){case 2:return "AUTH_EXPIRE";case 3:return "AUTH_LEAVE";case 4:return "ASSOC_EXPIRE";case 8:return "ASSOC_LEAVE";case 15:return "4WAY_HANDSHAKE_TIMEOUT";case 36:return "STA_LEAVING";case 39:return "TIMEOUT";case 200:return "BEACON_TIMEOUT";case 201:return "NO_AP_FOUND";case 202:return "AUTH_FAIL";case 203:return "ASSOC_FAIL";case 204:return "HANDSHAKE_TIMEOUT";case 205:return "CONNECTION_FAIL";case 207:return "ROAMING";default:return "AUTRE";}}
void wifiEvent(WiFiEvent_t event,WiFiEventInfo_t info){uint32_t now=millis();if(event==ARDUINO_EVENT_WIFI_STA_CONNECTED){wifiAssociatedAt=now;wifiLastChannel=info.wifi_sta_connected.channel;memcpy(wifiLastBssid,info.wifi_sta_connected.bssid,6);++wifiAssociations;Serial.printf("[WIFI-DIAG] associe t=%lu ms canal=%u BSSID=%02X:%02X:%02X:%02X:%02X:%02X depuis_deconnexion=%lu ms\n",now,unsigned(wifiLastChannel),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],wifiLastDisconnectAt?now-wifiLastDisconnectAt:now);}else if(event==ARDUINO_EVENT_WIFI_STA_GOT_IP){wifiGotIpAt=now;++wifiGotIps;Serial.printf("[WIFI-DIAG] DHCP t=%lu ms delai_apres_association=%lu ms IP=%s RSSI=%ld dBm\n",now,wifiAssociatedAt?now-wifiAssociatedAt:0,WiFi.localIP().toString().c_str(),long(WiFi.RSSI()));}else if(event==ARDUINO_EVENT_WIFI_STA_DISCONNECTED){wifiLastDisconnectAt=now;wifiLastReason=info.wifi_sta_disconnected.reason;memcpy(wifiLastBssid,info.wifi_sta_disconnected.bssid,6);++wifiDisconnects;Serial.printf("[WIFI-DIAG] deconnexion t=%lu ms motif=%u (%s) BSSID=%02X:%02X:%02X:%02X:%02X:%02X RSSI_avant=%ld dBm\n",now,unsigned(wifiLastReason),wifiReason(wifiLastReason),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],long(wifiRssiLast));}else if(event==ARDUINO_EVENT_WIFI_STA_LOST_IP)Serial.printf("[WIFI-DIAG] perte IP t=%lu ms\n",now);}
void formatPa(uint16_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u",(a>>12)&15,(a>>8)&15,a&255);}
bool parsePa(const char* s,bool& configured,uint16_t& out){configured=false;out=0;if(!s||!*s)return true;unsigned a,l,d;char x;if(sscanf(s,"%u.%u.%u%c",&a,&l,&d,&x)!=3||a>15||l>15||d>255)return false;configured=true;out=(a<<12)|(l<<8)|d;return true;}
void formatIp(uint32_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u.%u",(a>>24)&255,(a>>16)&255,(a>>8)&255,a&255);}
bool parseIp(const char* s,uint32_t& out){unsigned a,b,c,d;char x;if(!s||sscanf(s,"%u.%u.%u.%u%c",&a,&b,&c,&d,&x)!=4||a<224||a>239||b>255||c>255||d>255)return false;out=(a<<24)|(b<<16)|(c<<8)|d;return true;}
bool parseUInt(const char* s,uint32_t lo,uint32_t hi,uint32_t& out){if(!s||!*s)return false;char* e=nullptr;unsigned long v=strtoul(s,&e,10);if(!e||*e||v<lo||v>hi)return false;out=v;return true;}
bool valid(const RouterConfig& c){uint8_t first=c.multicast>>24;return c.version==kConfigVersion&&first>=224&&first<=239&&c.port&&c.timeoutMs>=3000&&c.timeoutMs<=60000&&c.probeMs>=500&&c.probeMs<=10000&&c.probeMs<c.timeoutMs;}
bool loadConfig(){if(!prefs.begin(kNvs,true))return false;RouterConfig candidate;size_t n=prefs.getBytesLength("config")==sizeof(candidate)?prefs.getBytes("config",&candidate,sizeof(candidate)):0;prefs.end();if(n!=sizeof(candidate)||!valid(candidate))return false;config=candidate;return true;}
bool saveConfig(const RouterConfig& c){if(!valid(c)||!prefs.begin(kNvs,false))return false;size_t n=prefs.putBytes("config",&c,sizeof(c));prefs.end();return n==sizeof(c);}

void logUart(bool tx,uint8_t value){if(uartLogCount==kUartEvents)++uartLogLosses;else ++uartLogCount;uartLog[uartLogHead]={millis(),value,tx};uartLogHead=(uartLogHead+1)%kUartEvents;if(tx)++uartTxBytes;else ++uartRxBytes;}
void writeUart(uint8_t value){logUart(true,value);knxSerial.write(value);knxSerial.flush();}
void finishFrame();
void captureTpTestRx(uint8_t value){if(tpTest.rxLen<sizeof(tpTest.rx))tpTest.rx[tpTest.rxLen++]=value;}
void sendTpTestFrame(){CemiFrame cemi(1);cemi.messageCode(L_data_req);cemi.frameType(StandardFrame);cemi.repetition(RepetitionAllowed);cemi.systemBroadcast(Broadcast);cemi.priority(LowPriority);cemi.ack(AckRequested);cemi.addressType(GroupAddress);cemi.hopCount(6);cemi.sourceAddress(kPrototypeAddress);cemi.destinationAddress(kTestGroup);cemi.apdu().type(GroupValueWrite);cemi.apdu().data()[0]=(cemi.apdu().data()[0]&0xC0)|(tpTest.value?1:0);TpFrame tp(cemi);tpTest.tpLen=min(size_t(tp.size()),sizeof(tpTest.tp));memcpy(tpTest.tp,tp.data(),tpTest.tpLen);for(uint16_t i=0;i<tp.size();++i){uint8_t control=i+1==tp.size()?uint8_t(0x40|((i+1)&0x3F)):uint8_t(0x80|(i&0x3F));logUart(true,control);knxSerial.write(control);logUart(true,tp.data(i));knxSerial.write(tp.data(i));}knxSerial.flush();tpTest.uartRequested=true;tpTest.phase=TpTestPhase::ConfirmWait;Serial.printf("[TP-TX] demande UART %s 1.1.253 -> 2/0/0, TP:",tpTest.value?"ON":"OFF");for(uint8_t i=0;i<tpTest.tpLen;++i)Serial.printf(" %02X",tpTest.tp[i]);Serial.println();}
void finishTpTest(bool success,const char* error){tpTest.finished=millis();if(!success&&error)strlcpy(tpTest.error,error,sizeof(tpTest.error));writeUart(0x05);diag=Diag::BusMonitor;frameLen=0;setText(lastDiagnostic,sizeof(lastDiagnostic),"Bus monitor passif restaure apres essai TP manuel");Serial.printf("[TP-TX] %s; U_L_Data.con=0x%02X, confirmations=%u; Busmon restaure\n",success?"confirme":"non confirme",tpTest.confirm,tpTest.confirmCount);tpTest.phase=success?TpTestPhase::Done:TpTestPhase::Failed;}
void startTpTest(bool value){if(diag==Diag::BusMonitor&&frameLen)finishFrame();tpTest={};tpTest.value=value;tpTest.started=millis();strlcpy(tpTest.error,"En cours",sizeof(tpTest.error));diag=Diag::Idle;while(knxSerial.available())captureTpTestRx(knxSerial.read());writeUart(0x01);tpTest.phase=TpTestPhase::ResetWait;Serial.printf("[TP-TX] essai manuel %s demarre; sortie Busmon par U_Reset.req\n",value?"ON":"OFF");}
void serviceTpTest(){if(tpTest.phase==TpTestPhase::Idle||tpTest.phase==TpTestPhase::Done||tpTest.phase==TpTestPhase::Failed)return;while(knxSerial.available()){uint8_t v=knxSerial.read();logUart(false,v);captureTpTestRx(v);if(tpTest.phase==TpTestPhase::ResetWait&&v==0x03){tpTest.resetOk=true;writeUart(0x02);tpTest.phase=TpTestPhase::StateWait;}else if(tpTest.phase==TpTestPhase::StateWait&&(v&7)==7){tpTest.stateOk=true;tpTest.state=v;sendTpTestFrame();}else if(tpTest.phase==TpTestPhase::ConfirmWait&&(v&0x7F)==0x0B){tpTest.confirm=v;++tpTest.confirmCount;tpTest.tpConfirmed=(v&0x80)!=0;finishTpTest(tpTest.tpConfirmed,tpTest.tpConfirmed?nullptr:"U_L_Data.con signale un echec");return;}}const uint32_t age=millis()-tpTest.started;if(tpTest.phase==TpTestPhase::ResetWait&&age>500){finishTpTest(false,"Delai U_Reset.ind depasse");return;}if(tpTest.phase==TpTestPhase::StateWait&&age>1000){finishTpTest(false,"Delai U_State.ind depasse");return;}if(tpTest.phase==TpTestPhase::ConfirmWait&&age>2500){finishTpTest(false,"Delai U_L_Data.con depasse");return;}}
void onKnxUartError(hardwareSerial_error_t error){if(error==UART_PARITY_ERROR)++uartParityErrors;else if(error==UART_FRAME_ERROR)++uartFrameErrors;else if(error==UART_FIFO_OVF_ERROR)++uartOverflowErrors;}
void configureKnxUartParams(uint32_t baud,uint32_t format,bool inverted){knxSerial.end();uartInverted=inverted;knxSerial.begin(baud,format,KNX_RX_PIN,KNX_TX_PIN,uartInverted);knxSerial.onReceiveError(onKnxUartError);}
void configureKnxUartFormat(uint32_t format,bool inverted){configureKnxUartParams(KNX_UART_BAUD,format,inverted);}
void configureKnxUart(bool inverted){configureKnxUartFormat(SERIAL_8E1,inverted);}
void resetDiagnosticLogs(){uartLogHead=uartLogCount=0;uartLogLosses=uartRxBytes=uartTxBytes=0;uartParityErrors=uartFrameErrors=uartOverflowErrors=0;tpLogHead=tpLogCount=0;tpLogLosses=0;resetInd=stateInd=tpFrames=overflows=attempts=0;frameLen=0;}
UartConfigSnapshot readUartConfig(){UartConfigSnapshot s;uart_word_length_t bits;uart_parity_t parity;uart_stop_bits_t stop;uart_hw_flowcontrol_t flow;uart_get_baudrate(UART_NUM_2,&s.baud);if(uart_get_word_length(UART_NUM_2,&bits)==ESP_OK)s.dataBits=uint8_t(bits)+5;if(uart_get_parity(UART_NUM_2,&parity)==ESP_OK)s.parity=uint8_t(parity);if(uart_get_stop_bits(UART_NUM_2,&stop)==ESP_OK)s.stopBits=uint8_t(stop);if(uart_get_hw_flow_ctrl(UART_NUM_2,&flow)==ESP_OK)s.flow=uint8_t(flow);s.rxInv=UART2.conf0.rxd_inv;s.txInv=UART2.conf0.txd_inv;s.swFlow=UART2.flow_conf.sw_flow_con_en;s.rs485=UART2.rs485_conf.en;s.rs485Loop=UART2.rs485_conf.tx_rx_en;s.halfDuplex=s.rs485&&UART2.rs485_conf.rx_busy_tx_en;return s;}
void runLoopbackFormat(uint32_t format,LoopbackResult& result){configureKnxUartFormat(format,false);delay(5);result={};result.valid=true;result.serialConfig=format;result.effective=readUartConfig();uartParityErrors=uartFrameErrors=uartOverflowErrors=0;while(knxSerial.available())knxSerial.read();const uint8_t test[]={0x01,0x03,0x55,0xAA};knxSerial.write(test,sizeof(test));knxSerial.flush();delay(20);while(knxSerial.available()&&result.rxLen<sizeof(result.rx))result.rx[result.rxLen++]=knxSerial.read();delay(10);result.parityErrors=uartParityErrors;result.frameErrors=uartFrameErrors;result.overflowErrors=uartOverflowErrors;}
void runSweepFormat(uint32_t baud,uint32_t format,SweepResult& result){result={};result.valid=true;result.requestedBaud=baud;result.serialConfig=format;configureKnxUartParams(baud,format,false);uartParityErrors=uartFrameErrors=uartOverflowErrors=0;delay(10);result.effective=readUartConfig();while(knxSerial.available()&&result.preLen<sizeof(result.pre))result.pre[result.preLen++]=knxSerial.read();for(uint8_t p=0;p<3;++p){knxSerial.write(uint8_t(0x01));knxSerial.flush();delay(20);while(knxSerial.available()&&result.probeLen[p]<sizeof(result.probe[p])){uint8_t value=knxSerial.read();result.probe[p][result.probeLen[p]++]=value;if(value==0x03)++result.resetValid;}}if(result.resetValid==3){knxSerial.write(uint8_t(0x02));knxSerial.flush();delay(20);while(knxSerial.available()&&result.stateLen<sizeof(result.state))result.state[result.stateLen++]=knxSerial.read();}result.parityErrors=uartParityErrors;result.frameErrors=uartFrameErrors;result.overflowErrors=uartOverflowErrors;}

IPAddress multicastAddress(){return IPAddress(config.multicast>>24,(config.multicast>>16)&255,(config.multicast>>8)&255,config.multicast&255);}
const char* apciName(ApduType t){switch(t){case GroupValueRead:return "GroupValueRead";case GroupValueResponse:return "GroupValueResponse";case GroupValueWrite:return "GroupValueWrite";case IndividualAddressWrite:return "IndividualAddressWrite";case IndividualAddressRead:return "IndividualAddressRead";case IndividualAddressResponse:return "IndividualAddressResponse";case PropertyValueRead:return "PropertyValueRead";case PropertyValueResponse:return "PropertyValueResponse";case PropertyValueWrite:return "PropertyValueWrite";default:return "Autre APCI";}}
void formatGroup(uint16_t a,char* out,size_t cap){snprintf(out,cap,"%u/%u/%u",(a>>11)&31,(a>>8)&7,a&255);}
void leaveMulticast(){if(ipJoined){knxIpUdp.stop();ipJoined=false;Serial.println(F("[KNX-IP RX] Ecoute multicast arretee"));}}
void joinMulticast(){if(!ipListenEnabled||WiFi.status()!=WL_CONNECTED)return;leaveMulticast();++ipJoinAttempts;ipJoined=knxIpUdp.beginMulticast(multicastAddress(),config.port)==1;if(ipJoined){ipJoinedAt=millis();ipLastGotIps=wifiGotIps;Serial.printf("[KNX-IP RX] Ecoute seule active sur %s:%u, STA=%s\n",multicastAddress().toString().c_str(),config.port,WiFi.localIP().toString().c_str());}else{++ipErrors;Serial.println(F("[KNX-IP RX] Echec inscription multicast"));}}
void addIpLog(IPAddress remote,uint16_t port,CemiFrame& cemi,const uint8_t* raw,size_t rawLen){if(ipDisplayPaused){++ipLogLosses;return;}if(ipLogCount==kLogEntries)++ipLogLosses;else ++ipLogCount;IpLogEntry& e=ipLog[ipLogHead];e={};e.ms=millis();e.remoteIp=remote;e.remotePort=port;e.source=cemi.sourceAddress();e.destination=cemi.destinationAddress();e.group=cemi.addressType()==GroupAddress;e.hop=cemi.hopCount();e.apci=cemi.apdu().type();e.rawLen=min(rawLen,kLogRawBytes);e.truncated=rawLen>kLogRawBytes;memcpy(e.raw,raw,e.rawLen);const size_t add=raw[1],apduOffset=add+9,apduLength=size_t(raw[add+8])+1;if(apduOffset+apduLength<=rawLen){e.apduLen=min(apduLength,sizeof(e.apdu));memcpy(e.apdu,raw+apduOffset,e.apduLen);}ipLogHead=(ipLogHead+1)%kLogEntries;}
void processIpDatagram(uint8_t* data,size_t len,IPAddress remote,uint16_t port){
 ++ipDatagrams;
 if(len<6||data[0]!=6||data[1]!=0x10){++ipErrors;return;}
 const uint16_t service=(uint16_t(data[2])<<8)|data[3],declared=(uint16_t(data[4])<<8)|data[5];
 if(declared!=len){++ipErrors;return;}if(service!=RoutingIndication){ipLastIgnoredService=service;++ipIgnored;return;}
 const size_t cemiLen=len-6;if(cemiLen<10){++ipErrors;return;}uint8_t* cemiData=data+6;const size_t add=cemiData[1];
 if(add+10>cemiLen){++ipErrors;return;}const size_t expected=add+size_t(cemiData[add+8])+10;if(expected!=cemiLen){++ipErrors;return;}
 KnxIpRoutingIndication indication(data,len);CemiFrame& cemi=indication.frame();if(!cemi.valid()||cemi.messageCode()!=L_data_ind){++ipErrors;return;}
 ++ipTelegrams;addIpLog(remote,port,cemi,cemiData,cemiLen);
 char src[16],dst[16];formatPa(cemi.sourceAddress(),src,sizeof(src));if(cemi.addressType()==GroupAddress)formatGroup(cemi.destinationAddress(),dst,sizeof(dst));else formatPa(cemi.destinationAddress(),dst,sizeof(dst));
 Serial.printf("[KNX-IP RX #%lu] %s:%u %s -> %s (%s) %s hop=%u; candidat TP - non transmis, mode ecoute\n",ipTelegrams,remote.toString().c_str(),port,src,dst,cemi.addressType()==GroupAddress?"groupe":"individuelle",apciName(cemi.apdu().type()),cemi.hopCount());
}
void serviceIpListener(){
 if(!ipListenEnabled||WiFi.status()!=WL_CONNECTED){leaveMulticast();return;}if(!ipJoined||ipLastGotIps!=wifiGotIps)joinMulticast();if(!ipJoined)return;
 for(uint8_t handled=0;handled<4;++handled){int packet=knxIpUdp.parsePacket();if(packet<=0)break;IPAddress remote=knxIpUdp.remoteIP();uint16_t port=knxIpUdp.remotePort();if(size_t(packet)>kIpBufferSize){uint8_t discard[32];while(knxIpUdp.available())knxIpUdp.read(discard,min(size_t(knxIpUdp.available()),sizeof(discard)));++ipDatagrams;++ipErrors;continue;}uint8_t data[kIpBufferSize];int got=knxIpUdp.read(data,packet);if(got!=packet){++ipDatagrams;++ipErrors;continue;}processIpDatagram(data,got,remote,port);}
}

void startDiagnostic(){diag=Diag::Running;diagStart=millis();lastProbe=diagStart-config.probeMs;attempts=0;frameLen=0;setText(lastDiagnostic,sizeof(lastDiagnostic),"Diagnostic NCN5130 en cours");setText(lastError,sizeof(lastError),"Aucune");Serial.println(F("[NANOBCU] Diagnostic local demarre"));}
void startCleanDiagnostic(){diag=Diag::Idle;resetDiagnosticLogs();configureKnxUart(false);delay(5);startDiagnostic();}
void finishFrame(){if(diag!=Diag::BusMonitor||!frameLen)return;++tpFrames;if(tpLogCount==kTpLogEntries)++tpLogLosses;else ++tpLogCount;TpLogEntry& e=tpLog[tpLogHead];e={};e.ms=millis();e.len=frameLen;memcpy(e.raw,frame,frameLen);const size_t tpLen=frameLen&&frame[frameLen-1]==0xCC?frameLen-1:frameLen;if(tpLen>=9){const uint8_t npdu=frame[5],declared=npdu&0x0F;const size_t expected=size_t(declared)+8;if(expected==tpLen){e.source=(uint16_t(frame[1])<<8)|frame[2];e.destination=(uint16_t(frame[3])<<8)|frame[4];e.group=npdu&0x80;e.hop=(npdu>>4)&7;e.apduLen=min(size_t(declared)+1,sizeof(e.apdu));memcpy(e.apdu,frame+6,e.apduLen);e.apci=ApduType((uint16_t(e.apdu[0]&3)<<8)|(e.apdu[1]&0xC0));uint8_t checksum=0;for(size_t i=0;i<tpLen;++i)checksum^=frame[i];e.checksumOk=checksum==0xFF;e.decoded=true;}}tpLogHead=(tpLogHead+1)%kTpLogEntries;Serial.printf("[TP-RX #%lu] %u octets:",tpFrames,unsigned(frameLen));for(size_t i=0;i<frameLen;++i)Serial.printf(" %02X",frame[i]);Serial.println();frameLen=0;}
void serviceDiagnostic(){
 if(diag==Diag::BusMonitor&&frameLen&&elapsed(micros(),lastByteUs,NANOBCU_FRAME_GAP_US))finishFrame();
 while(knxSerial.available()){uint8_t v=knxSerial.read();logUart(false,v);if(diag==Diag::Running&&v==0x03){++resetInd;diag=Diag::ResetReceived;setText(lastDiagnostic,sizeof(lastDiagnostic),"U_Reset.ind recu; lecture etat NCN5130");writeUart(0x02);}
 else if(diag==Diag::ResetReceived&&(v&7)==7){++stateInd;diag=Diag::BusMonitor;setText(lastDiagnostic,sizeof(lastDiagnostic),"NCN5130 detecte; bus monitor passif actif");writeUart(0x05);Serial.printf("[NANOBCU] U_State.ind=0x%02X; bus monitor passif\n",v);}
 else if(diag==Diag::BusMonitor){lastByteUs=micros();if(frameLen<sizeof(frame))frame[frameLen++]=v;else{++overflows;frameLen=0;setText(lastError,sizeof(lastError),"Trame UART depasse 64 octets");}}
 else if(diag==Diag::ResetReceived){diag=Diag::ProtocolError;snprintf(lastError,sizeof(lastError),"Reponse etat inattendue 0x%02X",v);}}
 uint32_t now=millis();if(diag==Diag::Running&&elapsed(now,diagStart,config.timeoutMs)){diag=Diag::Absent;setText(lastDiagnostic,sizeof(lastDiagnostic),"NanoBCU non detecte");Serial.println(F("[NANOBCU] NanoBCU non detecte (normal si debranche)"));}
 else if(diag==Diag::Running&&elapsed(now,lastProbe,config.probeMs)){lastProbe=now;++attempts;writeUart(0x01);}
}

void metric(WebResponse& r,const char* label,const char* value){r.write("<div><span class='muted'>");r.write(label);r.write("</span><strong>");r.write(value);r.write("</strong></div>");}
const char* parityName(uint8_t p){return p==UART_PARITY_EVEN?"paire":p==UART_PARITY_ODD?"impaire":"aucune";}
void writeNcnState(WebResponse& r,uint8_t value){char v[160];snprintf(v,sizeof(v),"0x%02X : collision=%u, receive error=%u, transmit error=%u, protocol error=%u, temperature warning=%u",value,(value>>7)&1,(value>>6)&1,(value>>5)&1,(value>>4)&1,(value>>3)&1);r.write(v);}
void writeLoopResult(WebResponse& r,const char* name,const LoopbackResult& x){char v[256];r.write("<h3>");r.write(name);r.write("</h3>");if(!x.valid){r.write("<p class='muted'>Non execute.</p>");return;}snprintf(v,sizeof(v),"%lu bauds, %u bits, parite %s, stop=%u",x.effective.baud,x.effective.dataBits,parityName(x.effective.parity),x.effective.stopBits);r.write("<p>");r.write(v);snprintf(v,sizeof(v),"<br>Inversion RX/TX=%u/%u, flux HW/SW=%u/%u, RS485=%u, boucle RS485=%u, half-duplex=%u<br>RX: <code>",x.effective.rxInv,x.effective.txInv,x.effective.flow,x.effective.swFlow,x.effective.rs485,x.effective.rs485Loop,x.effective.halfDuplex);r.write(v);if(!x.rxLen)r.write("aucun");for(size_t i=0;i<x.rxLen;++i){snprintf(v,sizeof(v),"%02X%s",x.rx[i],i+1==x.rxLen?"":" ");r.write(v);}snprintf(v,sizeof(v),"</code><br>Erreurs parite/trame/debordement: %lu/%lu/%lu</p>",x.parityErrors,x.frameErrors,x.overflowErrors);r.write(v);}
void writeHex(WebResponse& r,const uint8_t* data,size_t len){char v[8];if(!len){r.write("aucun");return;}for(size_t i=0;i<len;++i){snprintf(v,sizeof(v),"%02X%s",data[i],i+1==len?"":" ");r.write(v);}}
void writeSweepResult(WebResponse& r,const SweepResult& x){char v[256];if(!x.valid)return;snprintf(v,sizeof(v),"<h3>%lu/8%s1</h3><p>Effectif: %lu bauds, %u bits, parite %s, stop=%u; inversion RX/TX=%u/%u; flux HW/SW=%u/%u; RS485=%u</p><p>Avant emission: <code>",x.requestedBaud,x.serialConfig==SERIAL_8E1?"E":"N",x.effective.baud,x.effective.dataBits,parityName(x.effective.parity),x.effective.stopBits,x.effective.rxInv,x.effective.txInv,x.effective.flow,x.effective.swFlow,x.effective.rs485);r.write(v);writeHex(r,x.pre,x.preLen);r.write("</code></p>");for(uint8_t p=0;p<3;++p){snprintf(v,sizeof(v),"<p>Sonde %u TX <code>01</code>, RX <code>",unsigned(p+1));r.write(v);writeHex(r,x.probe[p],x.probeLen[p]);r.write("</code></p>");}if(x.resetValid==3){r.write("<p>Trois U_Reset.ind=03 reconnus; U_State.req=02, RX <code>");writeHex(r,x.state,x.stateLen);r.write("</code></p>");}snprintf(v,sizeof(v),"<p>03 reconnus: %u/3; erreurs parite/trame/debordement: %lu/%lu/%lu</p>",x.resetValid,x.parityErrors,x.frameErrors,x.overflowErrors);r.write(v);}
const IpLogEntry* matchingIp(const TpLogEntry& tp){if(!tp.decoded)return nullptr;const IpLogEntry* best=nullptr;uint32_t bestDelta=501;for(size_t n=0;n<ipLogCount;++n){const IpLogEntry& ip=ipLog[(ipLogHead+kLogEntries-1-n)%kLogEntries];const uint32_t delta=tp.ms>ip.ms?tp.ms-ip.ms:ip.ms-tp.ms;if(delta<bestDelta&&tp.source==ip.source&&tp.destination==ip.destination&&tp.group==ip.group&&tp.apci==ip.apci&&tp.apduLen==ip.apduLen&&!memcmp(tp.apdu,ip.apdu,tp.apduLen)){best=&ip;bestDelta=delta;}}return best;}
